import { describe, expect, it, vi } from "vitest";
import {
	type Capabilities,
	capabilitiesSchema,
	type HistoryResponse,
	type SessionProjection,
	type TranscriptEntry,
} from "@/contracts";
import { createListStore } from "@/state/list-store";
import { HistoryWindow, releaseDeliveredSteers } from "./history-window";
import { rowIdentity } from "./runtime";
import { steerJournalOrderDeclared } from "./steer-journal-order";

/* REAL-SHAPE FRAMES. Every row below is the exact JSON the core relay emits at
 * local-operator 6bc8ad78 (#4395): generated by driving `ProjectionFold`
 * (prompt u1, tool t1, phone steer s1 painted at SEND time, tools t2 and t3,
 * then delivery of s1, then tool t4) and passing each `_projection_frame`
 * through `steer_journal_order_frame(declared=True|False)`. The builders only
 * vary the fields the core varies between those rows. */
const base = {
	text: "",
	tool_call_id: "",
	tool_name: "",
	tool_state: "interrupted",
	summary: "",
	intent: "",
	diff_added: 0,
	diff_removed: 0,
	elapsed_s: 0,
	error: "",
	details: {},
	images: [],
	videos: [],
	final: true,
	text_complete: true,
} as unknown as TranscriptEntry;
const user = (id: string, text: string): TranscriptEntry => ({
	...base,
	id,
	kind: "user",
	text,
});
const steer = (id: string, text: string): TranscriptEntry => ({
	...base,
	id,
	kind: "steer",
	text,
});
const tool = (call: string): TranscriptEntry =>
	({
		...base,
		id: `tc-${call}`,
		kind: "tool",
		tool_call_id: call,
		tool_name: "bash",
		tool_state: "done",
		summary: "true",
		elapsed_s: 0.1,
		details: { args: { command: "true" }, output: "ok" },
	}) as TranscriptEntry;
const frame = (...transcript: TranscriptEntry[]) =>
	({ transcript }) as SessionProjection;

const u1 = user("u1", "do the thing");
const [t1, t2, t3, t4] = ["t1", "t2", "t3", "t4"].map(tool) as [
	TranscriptEntry,
	TranscriptEntry,
	TranscriptEntry,
	TranscriptEntry,
];
/** Before delivery: identical for declaring and legacy streams. */
const held = frame(u1, t1, steer("s1", "also check X"), t2, t3);
/** First frame after delivery, `?steer_journal_order=1`. */
const deliveredDeclared = frame(u1, t1, t2, t3, user("s1", "also check X"));
/** The same frame for a stream that did not declare (byte-identical legacy). */
const deliveredLegacy = held;
/** One more tool round after delivery, declaring stream. */
const laterDeclared = frame(u1, t1, t2, t3, user("s1", "also check X"), t4);

const keys = (rows: readonly TranscriptEntry[]) =>
	rows.map((row) => `${row.kind}:${rowIdentity(row)}`);
const noPages = vi.fn(
	async (): Promise<HistoryResponse> => ({ entries: [], has_more: false }),
);

describe("steer journal order: the declaration", () => {
	const live = (capabilities: unknown) => ({
		capabilities: capabilitiesSchema.parse(capabilities),
		liveFrameAt: 1,
	});

	it("declares only on a live frame that advertises the capability", () => {
		expect(
			steerJournalOrderDeclared(
				live({ steer_journal_order: { available: true } }),
			),
		).toBe(true);
		// An older relay: no key at all.
		expect(steerJournalOrderDeclared(live({}))).toBe(false);
		expect(
			steerJournalOrderDeclared(
				live({ steer_journal_order: { available: false } }),
			),
		).toBe(false);
		expect(steerJournalOrderDeclared(live({ steer_journal_order: {} }))).toBe(
			false,
		);
		// Capabilities restored from disk are the last session's, not this
		// relay's answer (`ListSnapshot.liveFrameAt`): no declaration on them.
		expect(
			steerJournalOrderDeclared({
				capabilities: capabilitiesSchema.parse({
					steer_journal_order: { available: true },
				}),
				liveFrameAt: null,
			}),
		).toBe(false);
	});

	it("never promotes a cached advertisement through a flagless live frame or reconnect", () => {
		const store = createListStore();
		const advertised = {
			sessions: [],
			degraded: [],
			capabilities: capabilitiesSchema.parse({
				steer_journal_order: { available: true },
				remote_sessions: { available: true },
				stt: { available: true, path: "/api/stt" },
			}),
		};
		store.getState().applyFrame(advertised, 1, undefined, "cache");
		expect(steerJournalOrderDeclared(store.getState())).toBe(false);
		store.getState().applyFrame({ sessions: [], degraded: [] }, 2);
		expect(steerJournalOrderDeclared(store.getState())).toBe(false);
		expect(store.getState().capabilities.remote_sessions).toBeUndefined();
		expect(store.getState().capabilities.stt).toEqual({
			available: true,
			path: "/api/stt",
		});
		store.getState().applyFrame(advertised, 3);
		expect(steerJournalOrderDeclared(store.getState())).toBe(true);
		store.getState().markStale();
		store.getState().applyFrame({ sessions: [], degraded: [] }, 4);
		expect(steerJournalOrderDeclared(store.getState())).toBe(false);
		store.getState().applyFrame(advertised, 5);
		store
			.getState()
			.applyFrame({ sessions: [], degraded: [], capabilities: {} }, 6);
		expect(steerJournalOrderDeclared(store.getState())).toBe(false);
		store.getState().reset();
		store.getState().applyFrame(advertised, 7, undefined, "cache");
		store.getState().applyFrame({ sessions: [], degraded: [] }, 8);
		expect(steerJournalOrderDeclared(store.getState())).toBe(false);
	});

	it("parses the capability loosely and leaves an older frame without it", () => {
		const parsed: Capabilities = capabilitiesSchema.parse({
			steer_journal_order: { available: true, later_field: 2 },
		});
		expect(parsed.steer_journal_order).toEqual({
			available: true,
			later_field: 2,
		});
		expect(capabilitiesSchema.parse({}).steer_journal_order).toBeUndefined();
	});
});

describe("steer journal order: the held row moves once, at delivery", () => {
	it("seats a delivered steer after predecessors coalesced into the delivery frame", () => {
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(frame(u1, steer("s1", "also check X"), t1));
		reader.accept(frame(u1, t1, t2, user("s1", "also check X")));
		expect(keys(reader.visibleRows)).toEqual(
			keys([u1, t1, t2, user("s1", "also check X")]),
		);
		reader.accept(frame(u1, t1, t2, user("s1", "also check X"), t3));
		expect(keys(reader.visibleRows)).toEqual(
			keys([u1, t1, t2, user("s1", "also check X"), t3]),
		);
	});

	it("keeps send order when several tools and steers arrive in one delivery snapshot", () => {
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(frame(u1, steer("s1", "one"), t1, steer("s2", "two")));
		const delivered = [u1, t1, t2, t3, user("s1", "one"), user("s2", "two")];
		reader.accept(frame(...delivered));
		expect(keys(reader.visibleRows)).toEqual(keys(delivered));
		reader.accept(frame(...delivered, t4));
		expect(keys(reader.visibleRows)).toEqual(keys([...delivered, t4]));
	});

	it("does not release ambiguous movers, ambiguous anchors, hole boundaries or unanchored chains", () => {
		const s = steer("s1", "one");
		const delivered = user("s1", "one");
		const spine = [u1, s, t1];
		for (const [previous, incoming, boundaries] of [
			[[u1, s, s, t1], [u1, t1, t2, delivered], new Set<string>()],
			[spine, [u1, t1, t2, delivered, delivered], new Set<string>()],
			[spine, [t1, t1, t2, delivered], new Set<string>()],
			[[u1, s, t1, t1], [t1, t2, delivered], new Set<string>()],
			[spine, [u1, t1, t2, delivered], new Set(["s1"])],
			[spine, [t2, t3, delivered], new Set<string>()],
		] satisfies [TranscriptEntry[], TranscriptEntry[], Set<string>][]) {
			expect(releaseDeliveredSteers(previous, incoming, boundaries)).toBe(
				previous,
			);
		}
	});

	it("keeps a delivered steer that bounds a reconnect hole in its existing slot", async () => {
		const reader = new HistoryWindow(
			async () => ({ entries: [u1, t1], has_more: false }),
			() => {},
		);
		reader.accept(frame(u1, t1));
		await reader.load();
		reader.accept({
			...frame(u1, steer("s1", "one"), t2),
			transcript_head_pinned: true,
		});
		expect(reader.gapBefore).toBe("s1");
		reader.accept({
			...frame(u1, t2, t3, user("s1", "one")),
			transcript_head_pinned: true,
		});
		expect(keys(reader.visibleRows)).toEqual(
			keys([u1, t1, user("s1", "one"), t2, t3]),
		);
		expect(reader.gapBefore).toBe("s1");
	});

	it("a declaring stream's delivered steer takes its journal slot on screen", () => {
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(held);
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"steer:s1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
		]);
		reader.accept(deliveredDeclared);
		// Journal (= `/history`) order, the row repainted as `user`, once.
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
			"user:s1",
		]);
		reader.accept(laterDeclared);
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
			"user:s1",
			"tool:tool-call:t4",
		]);
	});

	it("also moves when a durable page already holds the rows above it", async () => {
		// The page read before delivery: the journal has no s1 yet.
		const fetch = vi.fn(
			async (): Promise<HistoryResponse> => ({
				entries: [u1, t1, t2],
				has_more: false,
			}),
		);
		const reader = new HistoryWindow(fetch, () => {});
		reader.accept(held);
		await reader.load();
		reader.accept(deliveredDeclared);
		reader.accept(laterDeclared);
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
			"user:s1",
			"tool:tool-call:t4",
		]);
	});

	it("an older relay's (or undeclared) frame leaves the steer where it was painted", () => {
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(held);
		const before = reader.visibleRows;
		reader.accept({ ...deliveredLegacy });
		expect(keys(reader.visibleRows)).toEqual(keys(before));
		expect(reader.visibleRows.map((row) => row.kind)).toContain("steer");
	});

	it("never moves a row that is already a user row, and never a still-held steer", () => {
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(held);
		// The same send-time frame again (still undelivered): nothing moves.
		reader.accept(frame(...held.transcript, t4));
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"steer:s1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
			"tool:tool-call:t4",
		]);
	});

	it("a delivered steer whose frame predecessor is not held keeps its slot", () => {
		// The core keeps the slot (and only flips the kind) when the anchor is
		// outside a capped frame; the phone must not invent a position either.
		const reader = new HistoryWindow(noPages, () => {});
		reader.accept(held);
		reader.accept(frame(user("s1", "also check X"), t2, t3, t4));
		expect(keys(reader.visibleRows)).toEqual([
			"user:u1",
			"tool:tool-call:t1",
			"user:s1",
			"tool:tool-call:t2",
			"tool:tool-call:t3",
			"tool:tool-call:t4",
		]);
	});

	it("drops and duplicates nothing across the whole sequence", () => {
		const reader = new HistoryWindow(noPages, () => {});
		for (const next of [
			held,
			deliveredDeclared,
			laterDeclared,
			laterDeclared,
		]) {
			reader.accept({ ...next });
			const shown = keys(reader.visibleRows).map((key) =>
				key.split(":").slice(1).join(":"),
			);
			expect(new Set(shown).size).toBe(shown.length);
			for (const row of next.transcript)
				expect(shown).toContain(rowIdentity(row));
		}
	});
});
